128	template <class T>
129	static T checkEnvVar(const char *EnvOptSet, const char *EnvOptFile,
130	                     std::string &OptFile) {
131	  const char *Str = ::getenv(EnvOptSet);
132	  if (!Str)
133	    return T{};
134	
135	  T OptVal = Str;
136	  if (const char *Var = ::getenv(EnvOptFile))
137	    OptFile = Var;
138	  return OptVal;
139	}
